	//----W-Craft WebSquare 변환 확인: include----//
include("../js/libRoundPanel.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/mgt.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/utils.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/common.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/session.js");

	//----W-Craft WebSquare 변환 확인: include----//
include("../js/PopupCalendar.js");
scwin.g_ACPT_NO = "";
scwin.gLastJob = "조회";
scwin.vScrenID = 'ULDMGT80236.gfm';
scwin.onpageload = function() {
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    scwin.g_ACPT_NO = frame.opener.scwin.g_ACPT_NO;
};
scwin.fn_List3 = function() {
    $c.cm.ShowWin(grd_List3);
    var url = "/docprocslog.do?method=listSchdlExtrcObject" + "&ACPT_NO=" + scwin.g_ACPT_NO + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List3.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_List3.Reset();
};
scwin.fn_List4 = function() {
    $c.cm.ShowWin(grd_List4);
    var url = "/docprocslog.do?method=listSchdlExtrcResult" + "&ACPT_NO=" + scwin.g_ACPT_NO + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List4.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_List4.Reset();
};
scwin.fn_List5 = function() {
    $c.cm.ShowWin(grd_List5);
    var url = "/docprocslog.do?method=listDisclsSchdlRegHist" + "&ACPT_NO=" + scwin.g_ACPT_NO + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List5.DataID = encodeURI(url);

	//----W-Craft WebSquare 변환 확인: Reset----//
    dts_List5.Reset();
};
scwin.fn_validCheck = function() {
    if (scwin.g_ACPT_NO == '') {
        alert("[접수번호]가 없습니다.");
        return false;
    }
    return true;
};
scwin.fn_Search = function() {
    if (!scwin.fn_validCheck()) {
        return;
    }
    scwin.fn_List3(); //일정추출 - 대상
    scwin.fn_List4(); //일정추출 - 결과
    scwin.fn_List5(); //일정추출 - 이력

};
scwin.fn_SetPosition = function(obj, name, itm) {
    for (var i = 1; i <= obj.CountRow; i++) {
        if (obj.getCellData(i, name) == itm) {
            obj.RowPosition = i;
            //obj.SetColumn(name);
            i = obj.CountRow + 1; //종료

        }
    }
};
scwin.fn_setContnId = function(obj, row) {
    scwin.g_ACPT_NO = obj.getCellData(eval(row), "ACPT_NO");
};
scwin.alert_error2 = function(dtsObj) {
    var USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (var i = 0; i < USER_DEFINE.length; i++) {

	//----W-Craft WebSquare 변환 확인: SrvErrCount----//
        var errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        var j;
        for (j = 0; j < errorCount; j++) {

	//----W-Craft WebSquare 변환 확인: SrvErrCode----//
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) == '0') {
                //'0' 임의로 떨군 INFO 메시지

	//----W-Craft WebSquare 변환 확인: SrvErrMsg----//
                alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                //기존 에러 메시지

	//----W-Craft WebSquare 변환 확인: SrvErrMsg----//

	//----W-Craft WebSquare 변환 확인: SrvErrCode----//
                alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
scwin.dts_List3_OnLoadError = function() {
    scwin.alert_error2(dts_List3);
    $c.cm.CloseWin('', grd_List3);
};
scwin.dts_List3_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_List3.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_List3);
};
scwin.dts_List4_OnLoadError = function() {
    scwin.alert_error2(dts_List4);
    $c.cm.CloseWin('', grd_List4);
};
scwin.dts_List4_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_List4.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_List4);
};
scwin.dts_List5_OnLoadError = function() {
    scwin.alert_error2(dts_List5);
    $c.cm.CloseWin('', grd_List5);
};
scwin.dts_List5_OnLoadCompleted = function(rowcount) {
    if (rowcount <= 0) {
        dts_List5.removeAll();
    }
    $c.cm.CloseWin(rowcount, grd_List5);
};
scwin.grd_List3_OnClick = function(row, colid) {
    var sSCHDL_ADM_ITM_TP_CD = dts_List3.getCellData(row, "SCHDL_ADM_ITM_TP_CD");
    scwin.fn_SetPosition(dts_List4, "SCHDL_ADM_ITM_TP_CD", sSCHDL_ADM_ITM_TP_CD);
    scwin.fn_SetPosition(dts_List5, "SCHDL_ADM_ITM_TP_CD", sSCHDL_ADM_ITM_TP_CD);
};
scwin.grd_List4_OnClick = function(row, colid) {
    var sSCHDL_ADM_ITM_TP_CD = dts_List4.getCellData(row, "SCHDL_ADM_ITM_TP_CD");
    scwin.fn_SetPosition(dts_List3, "SCHDL_ADM_ITM_TP_CD", sSCHDL_ADM_ITM_TP_CD);
    scwin.fn_SetPosition(dts_List5, "SCHDL_ADM_ITM_TP_CD", sSCHDL_ADM_ITM_TP_CD);
};
scwin.grd_List5_OnClick = function(row, colid) {
    var sSCHDL_ADM_ITM_TP_CD = dts_List5.getCellData(row, "SCHDL_ADM_ITM_TP_CD");
    scwin.fn_SetPosition(dts_List3, "SCHDL_ADM_ITM_TP_CD", sSCHDL_ADM_ITM_TP_CD);
    scwin.fn_SetPosition(dts_List4, "SCHDL_ADM_ITM_TP_CD", sSCHDL_ADM_ITM_TP_CD);
};
scwin.btn_Excel3_onclick = function() {
    var file_name = "추출대상";
    var today = $c.ut.cGetToday('yyyymmddhhmmss');
    var xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
    $c.data.downloadGridViewOffice(grd_List3, file_name, xls_path, "8", 0);
};
scwin.btn_Excel4_onclick = function() {
    var file_name = "추출결과";
    var today = $c.ut.cGetToday('yyyymmddhhmmss');
    var xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
    $c.data.downloadGridViewOffice(grd_List4, file_name, xls_path, "8", 0);
};
scwin.btn_Excel5_onclick = function() {
    var file_name = "추출이력";
    var today = $c.ut.cGetToday('yyyymmddhhmmss');
    var xls_path = $c.session.getExcelDownPath() + today + "_" + file_name + ".xlsx";
    $c.data.downloadGridViewOffice(grd_List5, file_name, xls_path, "8", 0);
};
scwin.gform_onload = function() {
    scwin.fn_SetCode();
    scwin.fn_Search();
};
